import java.io.*;
import java.nio.file.*;
import java.util.*;
public class StowRun {
  public static int run(String reel) throws Exception {
    Gear g = Gear.load("/app/gearpit/live.gear");
    byte[] src = Files.readAllBytes(Paths.get(reel));
    String name = Paths.get(reel).getFileName().toString();
    Path marks = Paths.get("/app/urnbay/marks");
    Path mk = marks.resolve(name + ".m");
    Path flag = marks.resolve(name + ".flag");
    Files.createDirectories(marks);
    Map<String,String> idx = Idx.load();

    // A manifest is the authoritative segmentation of an already stored reel.
    // Check it before rechunking: gear changes must not defeat exact-reel reuse.
    List<String> oldKeys = readKeys(mk);
    if (!oldKeys.isEmpty() && Arrays.equals(src, materialize(oldKeys, idx))) {
      writeCard(name, src.length, 0, 1.0,
          src.length / (double) oldKeys.size(), oldKeys.size());
      Files.writeString(flag, "1\n");
      return 0;
    }

    List<byte[]> parts = Slice.cut(src, g.mask, g.min, g.max);
    long stored = 0;
    long reused = 0;
    List<String> keys = new ArrayList<>();
    Path hot = Paths.get("/app/urnbay/hot");
    Files.createDirectories(hot);
    for (byte[] p : parts) {
      String key = Seal.pay(p);
      String hit = idx.containsKey(key) ? key : null;
      if (hit != null) {
        reused += p.length;
        keys.add(hit);
      } else {
        stored += p.length;
        String rel = "hot/" + key + ".blob";
        Files.write(hot.resolve(key + ".blob"), p);
        Idx.put(key, rel);
        idx.put(key, rel);
        keys.add(key);
      }
    }
    StringBuilder mb = new StringBuilder();
    for (String k : keys) mb.append(k).append('\n');
    Files.writeString(mk, mb.toString());
    double reuse = src.length == 0 ? 1.0 : reused / (double) src.length;
    double mean = parts.isEmpty() ? 0.0 : src.length / (double) parts.size();
    writeCard(name, src.length, stored, reuse, mean, parts.size());
    Files.writeString(flag, "1\n");
    return 0;
  }

  static List<String> readKeys(Path mk) throws Exception {
    List<String> keys = new ArrayList<>();
    if (!Files.exists(mk)) return keys;
    for (String line : Files.readAllLines(mk)) {
      String key = line.trim();
      if (!key.isEmpty()) keys.add(key);
    }
    return keys;
  }

  static byte[] materialize(List<String> keys, Map<String,String> idx) throws Exception {
    ByteArrayOutputStream out = new ByteArrayOutputStream();
    for (String key : keys) {
      String rel = idx.get(key);
      if (rel == null) return null;
      Path blob = Paths.get("/app/urnbay").resolve(rel).normalize();
      if (!Files.isRegularFile(blob)) return null;
      out.write(Files.readAllBytes(blob));
    }
    return out.toByteArray();
  }

  static void writeCard(String name, long input, long stored, double reuse,
                        double mean, int count) throws Exception {
    String json = "{\n"
      + "  \"reel\": \"" + name.replace("\\", "\\\\").replace("\"", "\\\"") + "\",\n"
      + "  \"bytes_in\": \"" + input + "\",\n"
      + "  \"bytes_stored\": \"" + stored + "\",\n"
      + "  \"reuse_frac\": \"" + String.format(Locale.US, "%.4f", reuse) + "\",\n"
      + "  \"mean_piece\": \"" + String.format(Locale.US, "%.4f", mean) + "\",\n"
      + "  \"piece_count\": \"" + count + "\"\n"
      + "}\n";
    Files.writeString(Paths.get("/app/urnbay/tally.json"), json);
    Files.writeString(Paths.get("/app/urnbay/last.json"), json);
  }
}
